import{_ as t,o as e,c as l,a3 as n,j as a}from"./chunks/framework.Cc-oPviL.js";const h=JSON.parse('{"title":"03 · 隔离级别与 MVCC","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/db/03.md","filePath":"bagu/db/03.md"}'),p={name:"bagu/db/03.md"};function o(i,s,r,d,c,g){return e(),l("div",null,[...s[0]||(s[0]=[n(`<h1 id="_03-·-隔离级别与-mvcc" tabindex="-1">03 · 隔离级别与 MVCC <a class="header-anchor" href="#_03-·-隔离级别与-mvcc" aria-label="Permalink to &quot;03 · 隔离级别与 MVCC&quot;">​</a></h1><blockquote><p>数据库最抽象的一篇。<strong>必须画图</strong>，画一次就通了。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>并发事务会互相干扰。<strong>隔离级别</strong>决定&quot;允许干扰到什么程度&quot;，<strong>MVCC</strong> 用&quot;多版本&quot;实现&quot;读不阻塞写、写不阻塞读&quot;。</p><h2 id="生活类比-同一份文件的多个版本" tabindex="-1">生活类比：同一份文件的多个版本 <a class="header-anchor" href="#生活类比-同一份文件的多个版本" aria-label="Permalink to &quot;生活类比：同一份文件的多个版本&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你在写一份文档（事务 A），同时同事在看（事务 B）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>加锁方案（悲观）：</span></span>
<span class="line"><span>  A 开始写 &gt; 把文档锁住 &gt; B 想看得排队</span></span>
<span class="line"><span>  &gt; 安全，但 B 干等着，效率低</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MVCC 方案（乐观）：</span></span>
<span class="line"><span>  A 修改时，生成&quot;版本 2&quot;，原来的&quot;版本 1&quot;保留</span></span>
<span class="line"><span>  B 来读 &gt; 读&quot;版本 1&quot;（他开始时看到的那个版本）</span></span>
<span class="line"><span>  &gt; B 不用等，A 也不用等</span></span>
<span class="line"><span>  &gt; 等 A 提交后，B 下次读才能看到版本 2</span></span></code></pre></div><p><strong>核心</strong>：<strong>每个人看到的是&quot;自己开始时的那份快照&quot;</strong>，而不是&quot;最新的&quot;。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、三种异常-必须能举例" tabindex="-1">一、三种异常（必须能举例） <a class="header-anchor" href="#一、三种异常-必须能举例" aria-label="Permalink to &quot;一、三种异常（必须能举例）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>表：account(id, balance)   初始 id=1, balance=100</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【脏读】读到了别人未提交的修改</span></span>
<span class="line"><span>  事务 A：UPDATE balance = 200        （未提交）</span></span>
<span class="line"><span>  事务 B：SELECT balance &gt; 读到 200    &lt; 脏读</span></span>
<span class="line"><span>  事务 A：ROLLBACK                     &gt; 实际还是 100</span></span>
<span class="line"><span>  &gt; B 读到的 200 是&quot;从未存在过&quot;的数据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【不可重复读】同一事务内两次读同一行，值不同</span></span>
<span class="line"><span>  事务 B：SELECT balance &gt; 100</span></span>
<span class="line"><span>  事务 A：UPDATE balance = 200，COMMIT</span></span>
<span class="line"><span>  事务 B：SELECT balance &gt; 200         &lt; 不可重复读</span></span>
<span class="line"><span>  &gt; 同一事务内，读到了不同的值</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【幻读】同一事务内两次范围查询，行数不同</span></span>
<span class="line"><span>  事务 B：SELECT * FROM account WHERE id &gt; 0  &gt; 1 行</span></span>
<span class="line"><span>  事务 A：INSERT INTO account VALUES(2, 50)，COMMIT</span></span>
<span class="line"><span>  事务 B：SELECT * FROM account WHERE id &gt; 0  &gt; 2 行   &lt; 幻读</span></span>
<span class="line"><span>  &gt; 多出了&quot;幻影行&quot;</span></span></code></pre></div><p><strong>不可重复读 vs 幻读的关键区别</strong>：</p><ul><li>不可重复读：<strong>同一行</strong>的内容变了（UPDATE/DELETE）</li><li>幻读：<strong>结果集的行数</strong>变了（INSERT）</li></ul><p><strong>为什么这个区分重要</strong>：因为解法不同——不可重复读用行锁/MVCC 快照就够，幻读需要<strong>间隙锁</strong>（锁住&quot;可能插入的位置&quot;）。</p><h3 id="二、四个隔离级别" tabindex="-1">二、四个隔离级别 <a class="header-anchor" href="#二、四个隔离级别" aria-label="Permalink to &quot;二、四个隔离级别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>脏读</th><th>不可重复读</th><th>幻读</th><th>实现方式</th></tr></thead><tbody><tr><td><strong>读未提交</strong>（RU）</td><td>✅</td><td>✅</td><td>✅</td><td>什么都不做</td></tr><tr><td><strong>读已提交</strong>（RC）</td><td>❌</td><td>✅</td><td>✅</td><td>每次 SELECT 生成新 ReadView</td></tr><tr><td><strong>可重复读</strong>（RR，MySQL 默认）</td><td>❌</td><td>❌</td><td>⚠️ 基本解决</td><td>事务开始时生成 ReadView + 间隙锁</td></tr><tr><td><strong>串行化</strong></td><td>❌</td><td>❌</td><td>❌</td><td>所有读加共享锁，写加排他锁</td></tr></tbody></table><p><strong>为什么 MySQL 默认是 RR 而不是 RC</strong>：</p><ol><li>早期 MySQL 的 binlog 只有 statement 格式，RC 级别下主从可能不一致（同一 SQL 在主从执行顺序不同，结果不同）。RR 能避免。</li><li>RR 在同一事务内读到一致快照，对业务更友好。</li></ol><p><strong>但现在很多公司改成 RC</strong>（比如阿里）：RC 的锁范围更小、并发更高，且现在 binlog 默认是 row 格式，不存在一致性问题。</p><h3 id="三、mvcc-的三个组成部分" tabindex="-1">三、MVCC 的三个组成部分 <a class="header-anchor" href="#三、mvcc-的三个组成部分" aria-label="Permalink to &quot;三、MVCC 的三个组成部分&quot;">​</a></h3><h4 id="组成-1-隐藏字段" tabindex="-1">组成 1：隐藏字段 <a class="header-anchor" href="#组成-1-隐藏字段" aria-label="Permalink to &quot;组成 1：隐藏字段&quot;">​</a></h4><p>InnoDB 给每行加了三个隐藏字段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-- id            主键</span></span>
<span class="line"><span>+-- balance       业务字段</span></span>
<span class="line"><span>+-- DB_TRX_ID     最后修改这一行的事务 ID</span></span>
<span class="line"><span>+-- DB_ROLL_PTR   指向 undo log 的指针（版本链的链条）</span></span>
<span class="line"><span>+-- DB_ROW_ID     没有主键时用的隐藏行 ID</span></span></code></pre></div><h4 id="组成-2-undo-log-版本链" tabindex="-1">组成 2：undo log 版本链 <a class="header-anchor" href="#组成-2-undo-log-版本链" aria-label="Permalink to &quot;组成 2：undo log 版本链&quot;">​</a></h4>`,23),a("figure",{class:"fig"},[a("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),a("svg",{viewBox:"0 0 680 216",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"undo log 版本链与 ReadView 可见性判断"},[a("defs",null,[a("marker",{id:"arw-mvcc",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto"},[a("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),a("path",{class:"f-line",d:"M160 72 H225","marker-end":"url(#arw-mvcc)"}),a("path",{class:"f-line",d:"M355 72 H420","marker-end":"url(#arw-mvcc)"}),a("path",{class:"f-line",d:"M550 72 H598","marker-end":"url(#arw-mvcc)"}),a("rect",{class:"f-box-hi",x:"30",y:"48",width:"130",height:"48",rx:"8"}),a("text",{class:"f-title",x:"95",y:"70","text-anchor":"middle"},"balance=300"),a("text",{class:"f-mono",x:"95",y:"88","text-anchor":"middle"},"trx_id=50"),a("rect",{class:"f-box",x:"225",y:"48",width:"130",height:"48",rx:"8"}),a("text",{class:"f-title",x:"290",y:"70","text-anchor":"middle"},"balance=200"),a("text",{class:"f-mono",x:"290",y:"88","text-anchor":"middle"},"trx_id=40"),a("rect",{class:"f-box",x:"420",y:"48",width:"130",height:"48",rx:"8"}),a("text",{class:"f-title",x:"485",y:"70","text-anchor":"middle"},"balance=100"),a("text",{class:"f-mono",x:"485",y:"88","text-anchor":"middle"},"trx_id=30"),a("text",{class:"f-mono",x:"618",y:"76","text-anchor":"middle"},"NULL"),a("text",{class:"f-label",x:"95",y:"32","text-anchor":"middle"},"当前行（链头）"),a("text",{class:"f-mono",x:"192",y:"32","text-anchor":"middle"},"DB_ROLL_PTR"),a("text",{class:"f-label",x:"290",y:"32","text-anchor":"middle"},"undo log 旧版本"),a("text",{class:"f-label",x:"95",y:"118","text-anchor":"middle"},"不可见：50 在 m_ids 里"),a("text",{class:"f-label",x:"290",y:"118","text-anchor":"middle"},"不可见：40 在 m_ids 里"),a("text",{class:"f-title",x:"485",y:"118","text-anchor":"middle"},"可见：30 < min_trx_id"),a("rect",{class:"f-box",x:"30",y:"146",width:"620",height:"54",rx:"8"}),a("text",{class:"f-title",x:"46",y:"178"},"ReadView 快照："),a("text",{class:"f-mono",x:"170",y:"178"},"m_ids = [40, 45, 50] · min_trx_id = 40 · max_trx_id = 51")]),a("figcaption",{class:"fig-cap"},"ReadView 就是一张「我出生那一刻谁还活着」的名单。顺着 DB_ROLL_PTR 从最新版本往回走，第一个通过判断的版本就是你能看到的——所以 RC 和 RR 的差别只在 ReadView 什么时候生成。")],-1),n(`<p>每次修改都会产生一个新版本，用 <code>DB_ROLL_PTR</code> 串成链，<strong>链头是最新版本</strong>。链上每个版本都带着&quot;是谁改的&quot;（<code>trx_id</code>），所以能不能看见它，取决于读它的事务手里的那份 ReadView——就是下一节。</p><h4 id="组成-3-readview-读视图" tabindex="-1">组成 3：ReadView（读视图） <a class="header-anchor" href="#组成-3-readview-读视图" aria-label="Permalink to &quot;组成 3：ReadView（读视图）&quot;">​</a></h4><p>ReadView 是&quot;<strong>我在这个时刻能看到哪些事务的结果</strong>&quot;的一份快照。四个关键字段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>m_ids         ：生成 ReadView 时，所有&quot;活跃（未提交）&quot;的事务 ID 列表</span></span>
<span class="line"><span>min_trx_id    ：m_ids 里最小的</span></span>
<span class="line"><span>max_trx_id    ：生成 ReadView 时，下一个将要分配的事务 ID</span></span>
<span class="line"><span>creator_trx_id：创建这个 ReadView 的事务自己的 ID</span></span></code></pre></div><p><strong>可见性判断规则</strong>（对版本链上每个版本，从链头开始判断）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设版本的 trx_id = T</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① T == creator_trx_id</span></span>
<span class="line"><span>   &gt; 是我自己改的，可见 ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② T &lt; min_trx_id</span></span>
<span class="line"><span>   &gt; 这个事务在我开始前就提交了，可见 ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ T &gt;= max_trx_id</span></span>
<span class="line"><span>   &gt; 这个事务在我生成 ReadView 之后才开启，不可见 ❌</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ min_trx_id &lt;= T &lt; max_trx_id</span></span>
<span class="line"><span>   &gt; 看 T 是否在 m_ids 里</span></span>
<span class="line"><span>     在（还活跃）&gt; 不可见 ❌</span></span>
<span class="line"><span>     不在（已提交）&gt; 可见 ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果不可见，就顺着版本链往下找，直到找到可见的版本</span></span></code></pre></div><h3 id="四、rc-和-rr-的唯一区别-readview-的生成时机" tabindex="-1">四、RC 和 RR 的唯一区别：ReadView 的生成时机 <a class="header-anchor" href="#四、rc-和-rr-的唯一区别-readview-的生成时机" aria-label="Permalink to &quot;四、RC 和 RR 的唯一区别：ReadView 的生成时机&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RC（读已提交）：</span></span>
<span class="line"><span>  每次 SELECT 都生成一个新的 ReadView</span></span>
<span class="line"><span>  &gt; 所以能读到别人刚提交的数据（不可重复读）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RR（可重复读）：</span></span>
<span class="line"><span>  只在事务的第一次 SELECT 时生成 ReadView，之后复用</span></span>
<span class="line"><span>  &gt; 所以整个事务看到的是同一份快照（可重复读）</span></span></code></pre></div><p><strong>这是整篇最核心的一句话</strong>。MVCC 的实现两者完全一样，差别只在这一个时间点。</p><h3 id="五、快照读-vs-当前读" tabindex="-1">五、快照读 vs 当前读 <a class="header-anchor" href="#五、快照读-vs-当前读" aria-label="Permalink to &quot;五、快照读 vs 当前读&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>快照读（普通 SELECT）：</span></span>
<span class="line"><span>  SELECT * FROM user WHERE id = 1;</span></span>
<span class="line"><span>  &gt; 走 MVCC，读版本链里&quot;我能看到的那个版本&quot;</span></span>
<span class="line"><span>  &gt; 不加锁，不阻塞</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当前读（读最新版本，并加锁）：</span></span>
<span class="line"><span>  SELECT * FROM user WHERE id = 1 FOR UPDATE;      &gt; 加排他锁</span></span>
<span class="line"><span>  SELECT * FROM user WHERE id = 1 LOCK IN SHARE MODE; &gt; 加共享锁</span></span>
<span class="line"><span>  UPDATE / DELETE / INSERT                          &gt; 隐式当前读</span></span>
<span class="line"><span>  &gt; 读最新的已提交版本，并加锁</span></span></code></pre></div><p><strong>为什么 UPDATE 必须当前读</strong>：如果 UPDATE 读的是快照，那它可能基于一个旧版本修改，覆盖掉别人刚提交的数据（丢失更新）。</p><h3 id="六、幻读怎么解决" tabindex="-1">六、幻读怎么解决 <a class="header-anchor" href="#六、幻读怎么解决" aria-label="Permalink to &quot;六、幻读怎么解决&quot;">​</a></h3><p><strong>RR 级别下，MVCC 只能解决&quot;快照读&quot;的幻读</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务 B 的快照读：两次 SELECT 都看到 1 行  &lt; 因为快照没变，看不到新插入的行</span></span>
<span class="line"><span>但事务 B 如果执行 UPDATE（当前读）：</span></span>
<span class="line"><span>  UPDATE account SET balance = balance + 1 WHERE id &gt; 0;</span></span>
<span class="line"><span>  &gt; 会&quot;看到&quot;新插入的那一行，并修改它  &lt; 这就是幻读</span></span></code></pre></div><p><strong>所以 InnoDB 用间隙锁（Gap Lock）解决当前读的幻读</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>间隙锁锁住&quot;记录之间的空隙&quot;，让别人无法在这个空隙里插入</span></span>
<span class="line"><span></span></span>
<span class="line"><span>索引记录：id = 1, 5, 10</span></span>
<span class="line"><span>间隙：     (-∞,1) (1,5) (5,10) (10,+∞)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SELECT * FROM t WHERE id BETWEEN 3 AND 7 FOR UPDATE;</span></span>
<span class="line"><span>&gt; 锁住 (1,5) 和 (5,10) 两个间隙 + id=5 这条记录</span></span>
<span class="line"><span>&gt; 别人无法插入 id=4 或 id=6</span></span>
<span class="line"><span>&gt; 幻读被阻止</span></span></code></pre></div><p><strong>Next-Key Lock = 记录锁 + 间隙锁</strong>，锁住&quot;左开右闭&quot;的区间，比如 <code>(1, 5]</code>。这是 InnoDB 在 RR 下的默认加锁方式。</p><p><strong>RC 级别没有间隙锁</strong>（这也是它并发更高的原因，但会有幻读）。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果只用锁实现隔离" tabindex="-1">反事实 1：如果只用锁实现隔离 <a class="header-anchor" href="#反事实-1-如果只用锁实现隔离" aria-label="Permalink to &quot;反事实 1：如果只用锁实现隔离&quot;">​</a></h3><p>所有读都要加共享锁，所有写都要加排他锁。读写互相阻塞，并发度极低。</p><p>MVCC 让&quot;读&quot;完全不加锁（快照读），&quot;写&quot;只锁必要的行——<strong>读不阻塞写，写不阻塞读</strong>。这是现代数据库并发能力的来源。</p><h3 id="反事实-2-如果没有-undo-log-保存旧版本" tabindex="-1">反事实 2：如果没有 undo log 保存旧版本 <a class="header-anchor" href="#反事实-2-如果没有-undo-log-保存旧版本" aria-label="Permalink to &quot;反事实 2：如果没有 undo log 保存旧版本&quot;">​</a></h3><p>MVCC 无从实现——你没法&quot;读一个已经不存在的旧值&quot;。所以 undo log 既是回滚工具，也是 MVCC 的数据源。</p><h3 id="反事实-3-如果-readview-每次读都生成-也就是-rc" tabindex="-1">反事实 3：如果 ReadView 每次读都生成（也就是 RC） <a class="header-anchor" href="#反事实-3-如果-readview-每次读都生成-也就是-rc" aria-label="Permalink to &quot;反事实 3：如果 ReadView 每次读都生成（也就是 RC）&quot;">​</a></h3><p>那就是 RC 级别，会出现不可重复读。对于&quot;同一事务内要多次读同一数据&quot;的业务（比如先查余额再扣款），RC 会导致逻辑错误。</p><p><strong>RR 的价值就在这</strong>：给事务一个稳定的世界观。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：四个隔离级别？分别解决什么问题？</strong></p><blockquote><p>按表格答，重点说&quot;每个级别解决了上一级的哪个异常&quot;。再补一句&quot;MySQL 默认 RR，但很多公司改 RC，因为锁范围小、并发高&quot;。</p></blockquote><p><strong>Q：MVCC 怎么实现的？</strong></p><blockquote><p>三件套：<strong>隐藏字段</strong>（trx_id + roll_ptr）、<strong>undo log 版本链</strong>、<strong>ReadView</strong>。 然后讲可见性判断规则（四个分支）。</p></blockquote><p><strong>Q：RC 和 RR 的实现区别？</strong></p><blockquote><p><strong>只有一处</strong>：ReadView 的生成时机。RC 每次 SELECT 都生成新的，RR 只在第一次 SELECT 时生成并复用。</p></blockquote><p><strong>Q：MVCC 能解决幻读吗？</strong></p><blockquote><p><strong>只能解决快照读的幻读</strong>。当前读（UPDATE/DELETE/FOR UPDATE）仍然会看到新插入的行，需要靠<strong>间隙锁</strong>（Next-Key Lock）解决。</p></blockquote><p><strong>Q：什么是快照读和当前读？</strong></p><blockquote><p>快照读是普通 SELECT，走 MVCC 读历史版本，不加锁。当前读是 <code>FOR UPDATE</code>、<code>UPDATE</code>、<code>DELETE</code>，读最新版本并加锁。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>怎么解决不可重复读？（MVCC / RR 级别）</span></span>
<span class="line"><span>  &gt; MVCC 靠什么？（隐藏字段 + undo 版本链 + ReadView）</span></span>
<span class="line"><span>    &gt; ReadView 怎么判断可见？（四个分支）</span></span>
<span class="line"><span>      &gt; RC 和 RR 差在哪？（ReadView 生成时机）</span></span>
<span class="line"><span>        &gt; 那幻读解决了吗？（快照读解决了，当前读要靠间隙锁）</span></span>
<span class="line"><span>          &gt; 间隙锁有什么代价？（锁范围大，容易死锁）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/db/02">事务与 ACID</a>：undo log 是版本链的载体；隔离性是 ACID 的 I</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/03">调度与并发同步：CPU 分给谁，共享数据谁先动</a>：MVCC 是&quot;乐观并发控制&quot;，和 CAS 的思路一致（不锁，靠版本判断）</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/04">锁与死锁</a>：间隙锁是死锁的主要来源之一</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/05">SQL 执行与优化</a>：长事务导致 undo log 无法 purge，版本链变长，查询变慢</li><li><strong>&gt; 影响</strong> 工程实践：<code>SELECT ... FOR UPDATE</code> 用错会锁全表；RC 下没有间隙锁但要处理幻读</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么 RR 级别下，同一个事务两次 SELECT 结果一样，但 UPDATE 却能看到新插入的行？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>两种读走的是不同的路径</strong>：</p><ul><li><strong>普通 SELECT（快照读）</strong>：走 MVCC，用事务开始时生成的 ReadView 判断可见性。新插入的行 trx_id 在 ReadView 的 <code>max_trx_id</code> 之后（或者还在 m_ids 里），所以<strong>不可见</strong>。</li><li><strong>UPDATE（当前读）</strong>：必须读最新数据，否则会基于旧版本修改、覆盖别人的提交（丢失更新）。所以它绕过 MVCC，直接读最新版本并加锁。</li></ul><p><strong>这就产生了&quot;看起来矛盾&quot;的现象</strong>：SELECT 看不到，UPDATE 却改到了。</p><p>InnoDB 的补丁是<strong>间隙锁</strong>：在 RR 下，<code>UPDATE ... WHERE id &gt; 0</code> 会给范围加 Next-Key Lock，阻止别人在范围内插入。这样&quot;看不到也改不到&quot;，逻辑才自洽。</p></details><p><strong>Q2：ReadView 里 <code>m_ids</code> 存的是&quot;活跃事务&quot;，为什么要这个列表？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>光靠&quot;事务 ID 大小&quot;判断不了可见性</strong>。</p><p>假设事务 ID 是递增分配的：</p><ul><li>trx_id = 30（已提交）</li><li>trx_id = 40（还在跑，未提交）</li><li>trx_id = 50（已提交）</li><li>我是 trx_id = 60，现在生成 ReadView</li></ul><p>如果只看&quot;T &lt; 60 就可见&quot;，那 40 也会被判为可见——但 40 还没提交，读到它就是脏读。</p><p>所以需要 <code>m_ids = [40]</code> 这个列表，明确排除&quot;ID 比我小但还没提交&quot;的事务。</p><p><strong>本质上</strong>：事务 ID 小 ≠ 已提交。提交顺序和分配顺序不一致，所以必须显式记录&quot;谁还活着&quot;。</p></details><p><strong>Q3：为什么很多公司把隔离级别从 RR 改成 RC？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>三个原因：</p><ol><li><strong>RC 没有间隙锁</strong>，锁范围小，并发度高，死锁概率低。RR 的间隙锁是死锁的重灾区。</li><li><strong>RC 的主从一致性没问题了</strong>。早期 MySQL 的 binlog 只有 statement 格式，RC 下主从可能不一致；现在默认 row 格式，记录的是行的实际变更，不存在这个问题。</li><li><strong>RC 更符合直觉</strong>。大多数业务期望&quot;读到最后提交的数据&quot;，RR 的&quot;整个事务看到同一快照&quot;反而让一些场景困惑（比如查到了旧数据）。</li></ol><p><strong>代价</strong>：RC 有不可重复读和幻读，业务层要自己处理（比如用乐观锁版本号、或者关键操作加 <code>FOR UPDATE</code>）。</p><p><strong>结论</strong>：RR 是&quot;数据库帮你兜底&quot;，RC 是&quot;把控制权交给业务&quot;。规模大了通常选后者。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;多版本副本&quot;类比会让人以为真的复制了整行数据</strong>。实际 undo log 只记录<strong>被修改的字段的旧值</strong>，不是整行拷贝。</li><li><strong>MVCC 不是&quot;完全无锁&quot;</strong>。快照读无锁，但当前读（UPDATE/FOR UPDATE）要加锁。</li><li><strong>RR 不能完全解决幻读</strong>。只能解决快照读的，当前读要靠间隙锁。这是最常被答错的一点。</li><li><strong><code>m_ids</code> 不是&quot;所有未提交事务&quot;</strong>，是&quot;<strong>生成 ReadView 那一刻</strong>还活跃的事务&quot;。之后新开的、之后提交的，都不在里面。</li><li><strong>间隙锁只在 RR 及以上存在</strong>，RC 没有。所以&quot;RC 下为什么没有幻读&quot;这个问法本身就是错的——RC 有幻读。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能各举一个例子说明脏读、不可重复读、幻读（要能说清后两者的区别：值变 vs 行数变）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能默写四个隔离级别的表格（级别 × 三种异常）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出 MVCC 的三件套（隐藏字段 / undo 版本链 / ReadView），并画出结构图</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能背出 ReadView 的四个可见性判断分支</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能一句话说清&quot;RC 和 RR 的唯一区别&quot;（ReadView 生成时机）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释&quot;为什么 UPDATE 能看到 SELECT 看不到的行&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能说清间隙锁解决什么问题，以及它的代价</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,54)])])}const b=t(p,[["render",o]]);export{h as __pageData,b as default};
